mapper.select:
SELECT CAST(id AS varchar) AS id, CAST(account_id AS varchar) AS account_id, type, amount, balance_after, occurred_at
FROM phase3.transaction_history

  account_id = CAST(#{accountId} AS uuid)
  AND occurred_at >= #{fromInclusive}
  AND occurred_at < #{toExclusive}

ORDER BY occurred_at, id
